export interface RemoteAudioIdentity {
  peerId: string
  displayName: string
}

/** Reads the source player's UUID and display name from a remote stream id. */
export function readRemoteAudioIdentity(streamId: string, fallbackId: string): RemoteAudioIdentity {
  const match = /^svc:([^:]+):(.*)$/.exec(streamId)
  if (!match) return { peerId: fallbackId, displayName: fallbackId }

  const peerId = match[1] ?? fallbackId
  const encodedName = match[2] ?? ''
  let displayName = encodedName || peerId
  try {
    displayName = decodeURIComponent(encodedName.replace(/\+/g, '%20')) || peerId
  } catch {
    // A malformed name should not prevent the audio track from being used.
  }
  return { peerId, displayName }
}
