import Peer, { type DataConnection, type MediaConnection, type PeerJSOption } from 'peerjs'
import { t } from '@/i18n'
import { readRemoteAudioIdentity } from '@/audio/remoteAudioIdentity'
import {
  GROUP_REQUEST,
  GROUP_RESPONSE,
  newRequestId,
  readPayload,
  readRequestId,
  readType,
  toGroupError,
  toGroupInfo,
  toGroupList,
  type GroupInfo,
  type GroupJoinedPayload,
  type GroupLeftPayload,
  type GroupRequestId,
} from './GroupProtocol'

/** How long a group request waits for the plugin before giving up. */
const GROUP_TIMEOUT_MS = 8000

export interface PeerJsVoiceConnectionOptions {
  peerServer: Pick<PeerJSOption, 'host' | 'port' | 'path' | 'secure' | 'key'> & {
    token?: string
  }
  pluginPeerId: string
  code: string
  iceServers?: RTCIceServer[]
  debug?: 0 | 1 | 2 | 3
  onState?: (state: RTCPeerConnectionState | 'signaling') => void
  onStream?: (stream: MediaStream, peerId: string, displayName?: string) => void
  onError?: (error: Error) => void
  onDiagnostic?: (message: string) => void
  onChatMessage?: (message: { playerName?: string; message: string; system?: boolean }) => void
  onChatState?: (connected: boolean) => void
  /** A group invite pushed by the plugin (mod players invite browser players). */
  onGroupInvite?: (invite: { groupId: string; groupName: string; fromName: string; password?: string }) => void
  /** Reports the shared SVC group list from the plugin. */
  onGroupsChanged?: (groups: GroupInfo[]) => void
  onGroupJoined?: (payload: GroupJoinedPayload) => void
  /** Reports a failure the plugin answered with, even if no request is waiting. */
  onGroupError?: (message: string) => void
}

const CONNECTION_TIMEOUT_MS = 30_000

/**
 * Browser-side PeerJS media connection to exactly one plugin peer.
 *
 * PeerJS handles the browser connection to PeerServer and the browser-side
 * WebRTC negotiation. The plugin validates `metadata.code` before answering.
 */
export class PeerJsVoiceConnection {
  private peer: Peer | null = null
  private call: MediaConnection | null = null
  private chatConnection: DataConnection | null = null
  private closed = false
  private renegotiationTask: Promise<void> | null = null
  private readonly pendingRenegotiationCandidates: RTCIceCandidateInit[] = []
  /** Last group list the plugin reported, used to merge a single create answer. */
  private lastGroups: GroupInfo[] = []
  /**
   * One entry per waiting group request, keyed by correlation id. A
   * DataConnection is an eventemitter3, so it has no DOM style listener list;
   * instead of registering a pair of listeners per request, all requests share
   * the single `data` handler installed in `openChat` and are settled from
   * here. That is what keeps two parallel requests from taking each other's
   * answer.
   */
  private readonly pending = new Map<GroupRequestId, {
    expected: string
    resolve: (value: unknown) => void
    reject: (reason: Error) => void
    timer: ReturnType<typeof setTimeout>
  }>()

  constructor(private readonly options: PeerJsVoiceConnectionOptions) {}

  async connect(stream: MediaStream): Promise<void> {
    if (this.peer) throw new Error('PeerJS connection is already active')

    this.closed = false
    this.log(`Starting PeerJS connection to ${this.options.peerServer.host}:${this.options.peerServer.port}${this.options.peerServer.path}`)
    const peer = new Peer({
      ...this.options.peerServer,
      debug: this.options.debug ?? 1,
      config: {
        iceServers: this.options.iceServers ?? [
          { urls: 'stun:stun.l.google.com:19302' },
        ],
      },
    })
    this.peer = peer
    this.options.onState?.('signaling')

    await new Promise<void>((resolve, reject) => {
      let connectionTimeout: ReturnType<typeof setTimeout> | undefined
      const fail = (error: Error) => {
        if (connectionTimeout) clearTimeout(connectionTimeout)
        this.log(`Connection failed: ${this.redact(error.message)}`)
        this.close()
        peer.removeAllListeners()
        this.options.onError?.(error)
        reject(error)
      }

      peer.once('open', () => {
        if (this.closed) return reject(new Error('PeerJS connection was closed'))
        this.log('PeerJS signaling OPEN; requesting media call')
        const call = peer.call(this.options.pluginPeerId, stream, {
          metadata: { code: this.options.code },
        })
        if (!call) return fail(new Error('PeerJS konnte den Medienanruf nicht starten'))
        this.call = call
        this.bindCall(call)
        this.openChat(peer)
        call.on('iceStateChanged', state => this.log(`PeerJS ICE state: ${state}`))

        const pc = call.peerConnection
        const logRtcState = (event: string) => this.log(
          `${event}: connection=${pc.connectionState}, ice=${pc.iceConnectionState}, signaling=${pc.signalingState}, gathering=${pc.iceGatheringState}`,
        )
        pc.addEventListener('iceconnectionstatechange', () => logRtcState('ICE connection changed'))
        pc.addEventListener('signalingstatechange', () => logRtcState('Signaling state changed'))
        pc.addEventListener('icegatheringstatechange', () => logRtcState('ICE gathering changed'))
        pc.addEventListener('icecandidate', event => {
          if (!event.candidate) return this.log('ICE candidate gathering complete')
          const fields = event.candidate.candidate.split(' ')
          const type = fields[7] ?? 'unknown'
          const protocol = fields[2] ?? 'unknown'
          this.log(`Local ICE candidate: type=${type}, protocol=${protocol}`)
        })

        const reportConnectionState = () => {
          const state = pc.connectionState
          logRtcState('WebRTC connection changed')
          this.options.onState?.(state)
          if (state === 'connected') {
            if (connectionTimeout) clearTimeout(connectionTimeout)
            resolve()
          }
          else if (state === 'failed' || state === 'closed') {
            fail(new Error(`WebRTC-Verbindung fehlgeschlagen (${state}); ICE=${pc.iceConnectionState}, signaling=${pc.signalingState}`))
          }
        }
        pc.addEventListener('connectionstatechange', reportConnectionState)
        connectionTimeout = setTimeout(() => {
          if (pc.connectionState !== 'connected') {
            fail(new Error(`WebRTC-Timeout; connection=${pc.connectionState}, ICE=${pc.iceConnectionState}, signaling=${pc.signalingState}, gathering=${pc.iceGatheringState}`))
          }
        }, CONNECTION_TIMEOUT_MS)
        reportConnectionState()
      })
      peer.once('error', error => fail(this.toError(error)))
      peer.on('disconnected', () => this.log('PeerJS signaling disconnected'))
      peer.on('close', () => this.log('PeerJS signaling closed'))
    })
  }

  close(): void {
    this.closed = true
    this.failAllPending(new Error(t('group.transport.disconnected')))
    this.chatConnection?.close()
    this.chatConnection = null
    this.call?.close()
    this.call = null
    this.peer?.destroy()
    this.peer = null
  }

  getPeerId(): string | null {
    return this.peer?.id ?? null
  }

  /**
   * Tells the plugin that the player muted or deafened, so it can stop
   * forwarding audio. Without it the button only changed the local stream and
   * the server kept sending audio anyway.
   */
  sendVoiceState(kind: 'mute' | 'deafen', active: boolean): boolean {
    if (!this.chatConnection?.open) return false
    this.chatConnection.send({ type: kind, value: active })
    return true
  }

  /**
   * Group handling over the PeerJS data channel. Same five operations and the
   * same wire names as the direct WebSocket path, so both transports behave
   * identically. Here the plugin unwraps `payload`, so the fields travel
   * inside `payload` as well as next to it, which keeps this path working
   * whether or not the plugin unwraps.
   */
  private isGroupAnswer(type: string): boolean {
    return type === GROUP_RESPONSE.list
      || type === GROUP_RESPONSE.created
      || type === GROUP_RESPONSE.joined
      || type === GROUP_RESPONSE.left
      || type === GROUP_RESPONSE.error
  }

  private handleGroupAnswer(message: Record<string, unknown>, type: string): void {
    const payload = readPayload(message)
    const requestId = readRequestId(message)

    // The list is applied on sight: it answers a list request and is also the
    // follow up the plugin sends after a create, delete or leave.
    if (type === GROUP_RESPONSE.list) {
      const groups = toGroupList(payload)
      this.lastGroups = groups
      this.options.onGroupsChanged?.(groups)
    }

    if (type === GROUP_RESPONSE.created) {
      const created = toGroupInfo(payload)
      if (created) {
        this.lastGroups = this.mergeGroup(created)
        this.options.onGroupsChanged?.(this.lastGroups)
      }
    }

    if (type === GROUP_RESPONSE.joined) {
      const joined = payload as GroupJoinedPayload | undefined
      if (joined && typeof joined.groupId === 'string') this.options.onGroupJoined?.(joined)
    }

    // An error without a matching request is still worth showing, otherwise a
    // rejection from the plugin would disappear silently.
    if (type === GROUP_RESPONSE.error && !requestId) {
      this.options.onGroupError?.(toGroupError(payload, 'Das Plugin hat die Anfrage abgelehnt').message)
      return
    }

    // Only the request that owns this id may settle.
    if (!requestId) return
    const entry = this.pending.get(requestId)
    if (!entry) return

    if (type === GROUP_RESPONSE.error) {
      this.settlePending(requestId, () => entry.reject(
        new Error(toGroupError(payload, 'Das Plugin hat die Anfrage abgelehnt').message),
      ))
      return
    }
    if (type !== entry.expected) return
    this.settlePending(requestId, () => entry.resolve(payload))
  }

  private mergeGroup(group: GroupInfo): GroupInfo[] {
    if (this.lastGroups.some(existing => existing.id === group.id)) {
      return this.lastGroups.map(existing => (existing.id === group.id ? group : existing))
    }
    return [...this.lastGroups, group]
  }

  private settlePending(requestId: GroupRequestId, action: () => void): void {
    const entry = this.pending.get(requestId)
    if (!entry) return
    this.pending.delete(requestId)
    clearTimeout(entry.timer)
    action()
  }

  private failAllPending(error: Error): void {
    for (const [requestId, entry] of [...this.pending]) {
      this.settlePending(requestId, () => entry.reject(error))
    }
  }

  /** Asks the plugin for the shared SVC group list. */
  async requestGroupList(): Promise<GroupInfo[]> {
    const groups = await this.request<GroupInfo[]>(
      GROUP_REQUEST.list,
      GROUP_RESPONSE.list,
      {},
      payload => toGroupList(payload),
    )
    this.lastGroups = groups
    this.options.onGroupsChanged?.(groups)
    return groups
  }

  /** Creates a real SVC group, so mod players see and hear it too. */
  createGroup(data: { name: string; type: string; persistent: boolean; password?: string }): Promise<GroupInfo> {
    return this.request<GroupInfo>(
      GROUP_REQUEST.create,
      GROUP_RESPONSE.created,
      { name: data.name, type: data.type, persistent: data.persistent, ...(data.password ? { password: data.password } : {}) },
      payload => {
        const created = toGroupInfo(payload)
        if (!created) throw new Error(t('group.error.invalidGroup'))
        return created
      },
    )
  }

  deleteGroup(id: string): Promise<boolean> {
    return this.request<boolean>(GROUP_REQUEST.delete, GROUP_RESPONSE.list, { id }, () => true)
  }

  joinGroup(id: string, password?: string): Promise<GroupJoinedPayload> {
    return this.request<GroupJoinedPayload>(
      GROUP_REQUEST.join,
      GROUP_RESPONSE.joined,
      // The password only travels when there is one, so a normal join looks
      // exactly like it did before.
      password ? { id, password } : { id },
      payload => payload as GroupJoinedPayload,
    )
  }

  /** Leaves the group room, so the plugin stops counting us as a participant. */
  leaveGroup(id?: string): Promise<GroupLeftPayload> {
    return this.request<GroupLeftPayload>(
      GROUP_REQUEST.leave,
      GROUP_RESPONSE.left,
      { id: id ?? '' },
      payload => (payload as GroupLeftPayload) ?? { groupId: id ?? '' },
    )
  }

  /**
   * Sends one group request and waits for the answer with the same correlation
   * id. Every request settles exactly once: with the answer, with the
   * plugin's own error, or with a timeout the user can see.
   */
  private request<T>(
    type: string,
    expected: string,
    fields: Record<string, unknown>,
    parse: (payload: unknown) => T,
  ): Promise<T> {
    const connection = this.chatConnection
    if (!connection?.open) {
      return Promise.reject(new Error(t('group.transport.noPlugin')))
    }
    const requestId = newRequestId()
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.settlePending(requestId, () => reject(
          new Error(t('group.transport.timeout')),
        ))
      }, GROUP_TIMEOUT_MS)

      this.pending.set(requestId, {
        expected,
        resolve: value => resolve(parse(value)),
        reject,
        timer,
      })

      try {
        // The fields travel inside `payload` and next to it, so the plugin
        // finds them whether it unwraps or not.
        connection.send({ ...fields, type, payload: fields, requestId })
      } catch (error) {
        this.settlePending(requestId, () => reject(
          error instanceof Error ? error : new Error('Die Anfrage konnte nicht gesendet werden'),
        ))
      }
    })
  }

  sendChatMessage(message: string, command = false): boolean {
    if (!this.chatConnection?.open) return false
    this.chatConnection.send({ type: command ? 'command' : 'chat', message: message.trim().slice(0, 256) })
    return true
  }

  private openChat(peer: Peer): void {
    const connection = peer.connect(this.options.pluginPeerId, {
      label: 'svc-chat',
      reliable: true,
      serialization: 'json',
      metadata: { code: this.options.code },
    })
    this.chatConnection = connection
    connection.on('open', () => {
      this.log('Chat data channel opened')
      this.options.onChatState?.(true)
    })
    connection.on('data', payload => {
      if (!payload || typeof payload !== 'object') return
      const data = payload as Record<string, unknown>
      // Group answers travel the same channel, so they are handled before the
      // chat check below, which needs a message field.
      const type = readType(data)
      if (data['type'] === 'rtc-offer' && typeof data['sdp'] === 'string') {
        const task = this.answerRenegotiationOffer(data['sdp'])
        this.renegotiationTask = task
        void task.finally(() => {
          if (this.renegotiationTask === task) this.renegotiationTask = null
        void this.drainRenegotiationCandidates().catch(error => {
          this.options.onDiagnostic?.(`Remote ICE candidate failed: ${this.toError(error).message}`)
        })
        })
        return
      }
      if (data['type'] === 'rtc-candidate' && typeof data['candidate'] === 'string') {
        void this.applyRenegotiationCandidate({
          candidate: data['candidate'],
          sdpMid: typeof data['sdpMid'] === 'string' ? data['sdpMid'] : null,
          sdpMLineIndex: typeof data['sdpMLineIndex'] === 'number' ? data['sdpMLineIndex'] : 0,
        }).catch(error => {
          this.options.onDiagnostic?.(`Remote ICE candidate failed: ${this.toError(error).message}`)
        })
        return
      }
      if (type && this.isGroupAnswer(type)) {
        this.handleGroupAnswer(data, type)
        return
      }
      if (data['type'] === 'group-invite') {
        const groupId = data['groupId']
        const groupName = data['groupName']
        const fromName = data['fromName']
        if (typeof groupId !== 'string' || typeof groupName !== 'string' || typeof fromName !== 'string') return
        const password = data['password']
        this.options.onGroupInvite?.({
          groupId,
          groupName,
          fromName,
          ...(typeof password === 'string' && password ? { password } : {}),
        })
        return
      }
      if (typeof data['message'] !== 'string') return
      if (data['type'] === 'minecraft-chat' && typeof data['playerName'] === 'string') {
        this.log(`Minecraft chat received from ${data['playerName']} (${data['message'].length} chars)`)
        this.options.onChatMessage?.({ playerName: data['playerName'], message: data['message'] })
      } else if (data['type'] === 'server-message') {
        this.options.onChatMessage?.({ message: data['message'], system: true })
      }
    })
    connection.on('close', () => {
      this.options.onChatState?.(false)
      this.failAllPending(new Error(t('chat.channelClosed')))
    })
    connection.on('error', error => {
      this.log(`Chat data channel error: ${this.redact(this.toError(error).message)}`)
      this.options.onChatState?.(false)
    })
  }

  private bindCall(call: MediaConnection): void {
    call.on('stream', stream => {
      this.log(`Remote media stream received (${stream.getAudioTracks().length} audio tracks)`)
      const identity = readRemoteAudioIdentity(stream.id, this.options.pluginPeerId)
      this.options.onStream?.(stream, identity.peerId, identity.displayName)
    })
    call.on('close', () => {
      this.log('PeerJS media call closed')
      this.options.onState?.(call.peerConnection.connectionState)
    })
    call.on('error', error => {
      const converted = this.toError(error)
      this.log(`PeerJS media call error: ${this.redact(converted.message)}`)
      this.options.onError?.(converted)
    })
  }

  private async answerRenegotiationOffer(sdp: string): Promise<void> {
    const peerConnection = this.call?.peerConnection
    const dataConnection = this.chatConnection
    if (!peerConnection || !dataConnection?.open) return

    try {
      await peerConnection.setRemoteDescription({ type: 'offer', sdp })
      const answer = await peerConnection.createAnswer()
      await peerConnection.setLocalDescription(answer)
      if (answer.sdp) dataConnection.send({ type: 'rtc-answer', sdp: answer.sdp })
    } catch (error) {
      this.options.onDiagnostic?.(`Track renegotiation failed: ${this.toError(error).message}`)
    }
  }

  private async applyRenegotiationCandidate(candidate: RTCIceCandidateInit): Promise<void> {
    const peerConnection = this.call?.peerConnection
    if (!peerConnection) return
    const task = this.renegotiationTask
    if (task) {
      try {
        await task
      } catch {
        return
      }
    } else if (!peerConnection.remoteDescription) {
      this.pendingRenegotiationCandidates.push(candidate)
      return
    }
    await peerConnection.addIceCandidate(candidate)
  }

  private async drainRenegotiationCandidates(): Promise<void> {
    const peerConnection = this.call?.peerConnection
    if (!peerConnection?.remoteDescription) return
    const candidates = this.pendingRenegotiationCandidates.splice(0)
    for (const candidate of candidates) {
      await peerConnection.addIceCandidate(candidate)
    }
  }

  private log(message: string): void {
    this.options.onDiagnostic?.(message)
    console.info(`[voice-diagnostics] ${message}`)
  }

  private redact(message: string): string {
    return message
      .replaceAll(this.options.code, '[invite redacted]')
      .replaceAll(this.options.pluginPeerId, '[peer id redacted]')
  }

  private toError(error: unknown): Error {
    return error instanceof Error ? error : new Error(String(error))
  }
}
