import { SignalingClient } from '@/signaling/SignalingClient'
import { t } from '@/i18n'
import { readRemoteAudioIdentity } from '@/audio/remoteAudioIdentity'
import { WebRtcClient } from '@/webrtc/WebRtcClient'
import { createDeafenMessage, createMuteMessage } from '@/signaling/types'
import type { DeafenPayload, IceCandidatePayload, MutePayload } from '@/signaling/types'
import {
  GROUP_REQUEST,
  GROUP_RESPONSE,
  newRequestId,
  readPayload,
  readRequestId,
  readType,
  toGroupError,
  toGroupInfo,
  toGroupList,
  type GroupInfo,
  type GroupJoinedPayload,
  type GroupLeftPayload,
  type GroupRequestId,
} from './GroupProtocol'

/**
 * How long a group request waits for its answer. Long enough for a busy server
 * main thread, short enough that the user gets an error instead of a spinner
 * that never ends.
 */
const GROUP_TIMEOUT_MS = 8000

export interface ServerVoiceConnectionOptions {
  url: string
  token: string
  roomId: string
  displayName: string
  /** Microphone constraints built from the settings; defaults apply without it. */
  audioConstraints?: MediaTrackConstraints
  onState?: (state: RTCPeerConnectionState) => void
  onStream?: (stream: MediaStream, peerId: string, displayName?: string) => void
  /** Reports that the signaling connection to the server is gone. */
  onConnectionLost?: (reason: string) => void
  /** Reports the raw signaling state, used for the status display. */
  onSignalingState?: (state: string) => void
  /** Reports the shared SVC group list. */
  onGroupsChanged?: (groups: GroupInfo[]) => void
  /** Reports that this browser joined a group. */
  onGroupJoined?: (payload: GroupJoinedPayload) => void
  /** Reports a failure the plugin answered with, even if no request is waiting. */
  onGroupError?: (message: string) => void
}

/**
 * Owns exactly one browser ↔ plugin WebRTC session.
 *
 * Group handling lives here in full, over the direct WebSocket. The wire shape
 * is not the same as for the PeerJS path: the plugin's Netty handler decodes
 * the group fields from the top level of the message, so `name`, `id`,
 * `type` and `persistent` sit next to `payload` instead of inside it. Sending
 * them only inside `payload` made the plugin answer with
 * "Invalid group payload", which is why creating a group did nothing.
 */
export class ServerVoiceConnection {
  private readonly signaling: SignalingClient
  private readonly rtc: WebRtcClient
  private readonly options: ServerVoiceConnectionOptions
  private peerId: string | null = null
  private remoteAudio: HTMLAudioElement | null = null
  private remoteDescriptionInstalled = false
  private remoteOfferTask: Promise<void> | null = null
  private readonly pendingRemoteCandidates: RTCIceCandidateInit[] = []
  /** Reports that the signaling connection to the server died. */
  onConnectionLost: ((reason: string) => void) | null = null
  /** Reports the raw signaling state, used for the status display. */
  onSignalingState: ((state: string) => void) | null = null
  /** Reports the shared SVC group list. */
  onGroupsChanged: ((groups: GroupInfo[]) => void) | null = null
  /** Reports that this browser joined a group. */
  onGroupJoined: ((payload: GroupJoinedPayload) => void) | null = null
  /** Reports a failure the plugin answered with, even if no request is waiting. */
  onGroupError: ((message: string) => void) | null = null

  /**
   * One listener per waiting request, keyed by correlation id. The plugin
   * answers every request with a broadcast that has no id of its own, so the
   * request that sent first would otherwise swallow the answer meant for a
   * later one.
   */
  private readonly pending = new Map<GroupRequestId, {
    expected: string
    resolve: (value: unknown) => void
    reject: (reason: Error) => void
    timer: ReturnType<typeof setTimeout>
  }>()

  constructor(options: ServerVoiceConnectionOptions) {
    this.options = options
    this.signaling = new SignalingClient({ url: options.url })
    this.rtc = new WebRtcClient({
      audioConstraints: options.audioConstraints,
      onIceCandidate: candidate => this.sendIceCandidate(candidate),
      onConnectionStateChange: state => options.onState?.(state as RTCPeerConnectionState),
      onTrack: (_track, stream) => {
        const identity = readRemoteAudioIdentity(stream.id, this.peerId ?? 'remote')
        this.playRemoteStream(stream, identity.peerId, identity.displayName)
      },
    })
    this.onConnectionLost = options.onConnectionLost ?? null
    this.onSignalingState = options.onSignalingState ?? null
    this.onGroupsChanged = options.onGroupsChanged ?? null
    this.onGroupJoined = options.onGroupJoined ?? null
    this.onGroupError = options.onGroupError ?? null
    this.bindSignaling()
    this.bindGroupAnswers()
  }

  async connect(): Promise<MediaStream | null> {
    await this.rtc.initialize()
    await this.signaling.connect()
    await this.signaling.join({
      token: this.options.token,
      roomId: this.options.roomId,
      displayName: this.options.displayName,
    })
    return this.rtc.getLocalStream()
  }

  disconnect(): void {
    this.failAllPending(new Error(t('group.transport.disconnected')))
    this.signaling.disconnect()
    this.rtc.close()
    this.remoteAudio?.remove()
    this.remoteAudio = null
    this.peerId = null
  }

  setMuted(muted: boolean): void {
    this.rtc.setMuted(muted)
    // Without this the plugin never learns the mute state over this transport,
    // so it keeps forwarding audio and the status symbols stay wrong.
    this.sendVoiceState('mute', muted)
  }

  /**
   * Tells the plugin that this browser hears nothing. The plugin turns this
   * into the state Simple Voice Chat uses for its full mute symbol, so mod
   * players see the browser as silenced instead of still speaking.
   */
  setDeafened(deafened: boolean): void {
    this.sendVoiceState('deafen', deafened)
  }

  private sendVoiceState(type: 'mute' | 'deafen', active: boolean): void {
    const payload = type === 'mute' ? { muted: active } : { deafened: active }
    void this.signaling.sendMessage(
      type === 'mute' ? createMuteMessage(payload as MutePayload) : createDeafenMessage(payload as DeafenPayload),
    )
  }

  private bindSignaling(): void {
    // Without these the page never learns that the server went away, so it
    // keeps showing a healthy connection while nothing works any more.
    this.signaling.addEventListener('close', (event: Event) => {
      const detail = (event as CustomEvent<{ code: number; reason: string; wasClean: boolean }>).detail
      this.onConnectionLost?.(detail?.reason || t('group.transport.serverLost'))
    })
    this.signaling.addEventListener('error', () => {
      this.onConnectionLost?.(t('group.transport.serverFaulty'))
    })
    this.signaling.addEventListener('statechange', (event: Event) => {
      const { state } = (event as CustomEvent<{ state: string }>).detail
      this.onSignalingState?.(state)
    })
    this.signaling.addEventListener('joined', (event: Event) => {
      const { peerId } = (event as CustomEvent<{ peerId: string }>).detail
      this.peerId = peerId
      void this.sendOffer()
    })
    this.signaling.addEventListener('answer', (event: Event) => {
      const { sdp } = (event as CustomEvent<{ sdp: string }>).detail
      void this.rtc.setRemoteDescription({ type: 'answer', sdp }).then(async () => {
        this.remoteDescriptionInstalled = true
        await this.drainRemoteCandidates()
      }).catch(error => {
        console.error('Could not apply the initial WebRTC answer', error)
      })
    })
    this.signaling.addEventListener('offer', (event: Event) => {
      const { sdp } = (event as CustomEvent<{ sdp: string }>).detail
      const task = this.answerRenegotiationOffer(sdp)
      this.remoteOfferTask = task
      void task.finally(() => {
        if (this.remoteOfferTask === task) this.remoteOfferTask = null
        void this.drainRemoteCandidates().catch(error => {
          console.error('Could not apply a queued WebRTC ICE candidate', error)
        })
      })
    })
    this.signaling.addEventListener('icecandidate', (event: Event) => {
      const payload = (event as CustomEvent<IceCandidatePayload>).detail
      void this.applyRemoteCandidate({
        candidate: payload.candidate,
        sdpMid: payload.sdpMid,
        sdpMLineIndex: payload.sdpMLineIndex,
      }).catch(error => {
        console.error('Could not apply a WebRTC ICE candidate', error)
      })
    })
  }

  /**
   * One single place where every inbound group answer is handled, so a request
   * and the group list can never fight over the same message.
   */
  private bindGroupAnswers(): void {
    this.signaling.addEventListener('message', (event: Event) => {
      const { message } = (event as CustomEvent<{ message: unknown }>).detail
      const type = readType(message)
      if (!type) return
      if (type === GROUP_RESPONSE.list || type === GROUP_RESPONSE.created || type === GROUP_RESPONSE.joined || type === GROUP_RESPONSE.left || type === GROUP_RESPONSE.error) {
        this.handleGroupAnswer(message, type)
      }
    })
    // A plugin error also arrives as its own event; surface it so a rejected
    // request is visible even when its correlation id is missing.
    this.signaling.addEventListener('errorReceived', (event: Event) => {
      const detail = (event as CustomEvent<{ code: number; message: string }>).detail
      this.onGroupError?.(detail?.message || 'Das Plugin hat die Anfrage abgelehnt')
    })
  }

  private handleGroupAnswer(message: unknown, type: string): void {
    const payload = readPayload(message)
    const requestId = readRequestId(message)

    // The group list is always applied, because it is the answer to a list
    // request and also the follow up the plugin sends after a create, delete
    // or leave.
    if (type === GROUP_RESPONSE.list) {
      const groups = toGroupList(payload)
      this.lastGroups = groups
      this.onGroupsChanged?.(groups)
    }

    if (type === GROUP_RESPONSE.created) {
      const created = toGroupInfo(payload)
      if (created) {
        this.lastGroups = this.mergeGroup(created)
        this.onGroupsChanged?.(this.lastGroups)
      }
    }

    if (type === GROUP_RESPONSE.joined) {
      const joined = payload as GroupJoinedPayload | undefined
      if (joined && typeof joined.groupId === 'string') this.onGroupJoined?.(joined)
    }

    // Only the request that owns this id may settle.
    if (!requestId) return
    const entry = this.pending.get(requestId)
    if (!entry) return

    if (type === GROUP_RESPONSE.error) {
      this.settlePending(requestId, () => entry.reject(
        new Error(toGroupError(payload, 'Das Plugin hat die Anfrage abgelehnt').message),
      ))
      return
    }
    if (type !== entry.expected) return
    this.settlePending(requestId, () => entry.resolve(payload))
  }

  private mergeGroup(group: GroupInfo): GroupInfo[] {
    const current = this.lastGroups
    if (current.some(existing => existing.id === group.id)) {
      return current.map(existing => (existing.id === group.id ? group : existing))
    }
    return [...current, group]
  }

  private lastGroups: GroupInfo[] = []

  private settlePending(requestId: GroupRequestId, action: () => void): void {
    const entry = this.pending.get(requestId)
    if (!entry) return
    this.pending.delete(requestId)
    clearTimeout(entry.timer)
    action()
  }

  private failAllPending(error: Error): void {
    for (const [requestId, entry] of [...this.pending]) {
      this.settlePending(requestId, () => entry.reject(error))
    }
  }

  private async sendOffer(): Promise<void> {
    if (!this.peerId) return
    const offer = await this.rtc.createOffer()
    await this.signaling.sendOffer({
      roomId: this.options.roomId,
      to: this.peerId,
      sdp: offer.sdp ?? '',
    })
  }

  private async answerRenegotiationOffer(sdp: string): Promise<void> {
    if (!this.peerId) return
    try {
      const answer = await this.rtc.createAnswer({ type: 'offer', sdp })
      await this.signaling.sendAnswer({
        roomId: this.options.roomId,
        to: this.peerId,
        sdp: answer.sdp ?? '',
      })
    } catch (error) {
      console.error('WebRTC audio track renegotiation failed', error)
    }
  }

  private async applyRemoteCandidate(candidate: RTCIceCandidateInit): Promise<void> {
    const offerTask = this.remoteOfferTask
    if (offerTask) {
      await offerTask
      await this.rtc.addIceCandidate(candidate)
      return
    }
    if (!this.remoteDescriptionInstalled) {
      this.pendingRemoteCandidates.push(candidate)
      return
    }
    await this.rtc.addIceCandidate(candidate)
  }

  private async drainRemoteCandidates(): Promise<void> {
    if (!this.remoteDescriptionInstalled) return
    const candidates = this.pendingRemoteCandidates.splice(0)
    for (const candidate of candidates) {
      await this.rtc.addIceCandidate(candidate)
    }
  }

  private async sendIceCandidate(candidate: RTCIceCandidateInit): Promise<void> {
    if (!this.peerId || !candidate.candidate) return
    await this.signaling.sendIceCandidate({
      roomId: this.options.roomId,
      to: this.peerId,
      candidate: candidate.candidate,
      sdpMid: candidate.sdpMid ?? '',
      sdpMLineIndex: candidate.sdpMLineIndex ?? 0,
    })
  }

  /** Asks the plugin for the shared SVC group list. */
  async requestGroupList(): Promise<GroupInfo[]> {
    const groups = await this.request<GroupInfo[]>(
      GROUP_REQUEST.list,
      GROUP_RESPONSE.list,
      {},
      payload => toGroupList(payload),
    )
    this.lastGroups = groups
    this.onGroupsChanged?.(groups)
    return groups
  }

  /** Creates a real SVC group, so mod players see and hear it too. */
  createGroup(data: { name: string; type: string; persistent: boolean; password?: string }): Promise<GroupInfo> {
    return this.request<GroupInfo>(
      GROUP_REQUEST.create,
      GROUP_RESPONSE.created,
      { name: data.name, type: data.type, persistent: data.persistent, ...(data.password ? { password: data.password } : {}) },
      payload => {
        const created = toGroupInfo(payload)
        if (!created) throw new Error(t('group.error.invalidGroup'))
        return created
      },
    )
  }

  deleteGroup(id: string): Promise<boolean> {
    return this.request<boolean>(
      GROUP_REQUEST.delete,
      GROUP_RESPONSE.list,
      { id },
      () => true,
    )
  }

  joinGroup(id: string, password?: string): Promise<GroupJoinedPayload> {
    return this.request<GroupJoinedPayload>(
      GROUP_REQUEST.join,
      GROUP_RESPONSE.joined,
      // The password only travels when there is one, so a normal join looks
      // exactly like it did before.
      password ? { id, password } : { id },
      payload => payload as GroupJoinedPayload,
    )
  }

  /** Leaves the group room, so the plugin stops counting us as a participant. */
  leaveGroup(id?: string): Promise<GroupLeftPayload> {
    return this.request<GroupLeftPayload>(
      GROUP_REQUEST.leave,
      GROUP_RESPONSE.left,
      { id: id ?? '' },
      payload => (payload as GroupLeftPayload) ?? { groupId: id ?? '' },
    )
  }

  /**
   * Sends one group request and waits for the answer that carries the same
   * correlation id. Every request settles exactly once: with the answer, with
   * the plugin's own error, or with a timeout the user can see.
   */
  private request<T>(
    type: string,
    expected: string,
    fields: Record<string, unknown>,
    parse: (payload: unknown) => T,
  ): Promise<T> {
    const requestId = newRequestId()
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.settlePending(requestId, () => reject(
          new Error(t('group.transport.timeout')),
        ))
      }, GROUP_TIMEOUT_MS)

      this.pending.set(requestId, {
        expected,
        resolve: value => resolve(parse(value)),
        reject,
        timer,
      })

      // The plugin reads the group fields from the top level of the message,
      // so they travel next to `payload` and not inside it.
      void this.signaling
        .sendGroupMessage(type, fields, { requestId, ...fields })
        .then(sent => {
          if (!sent) {
            this.settlePending(requestId, () => reject(new Error('Keine Verbindung zum Plugin')))
          }
        })
        .catch(() => {
          this.settlePending(requestId, () => reject(new Error('Keine Verbindung zum Plugin')))
        })
    })
  }

  private playRemoteStream(stream: MediaStream, peerId: string, displayName: string): void {
    // Playback is owned by the store's mixer, which gives every participant
    // its own gain. This element is only the fallback for a store that does
    // not consume `onStream`.
    if (!this.options.onStream) {
      if (!this.remoteAudio) {
        this.remoteAudio = document.createElement('audio')
        this.remoteAudio.autoplay = true
        this.remoteAudio.setAttribute('aria-hidden', 'true')
        document.body.append(this.remoteAudio)
      }
      this.remoteAudio.srcObject = stream
      void this.remoteAudio.play().catch(() => undefined)
    }
    this.options.onStream?.(stream, peerId, displayName)
  }
}
