import { ref } from 'vue'
import type { AudioDeviceInfo } from '@/types'

type DeviceKind = 'audioinput' | 'audiooutput'

function toAudioDevice(
  device: Pick<MediaDeviceInfo, 'deviceId' | 'label' | 'groupId'>,
  kind: DeviceKind,
  fallbackPrefix: string,
): AudioDeviceInfo {
  return {
    deviceId: device.deviceId,
    label: device.label || `${fallbackPrefix} ${device.deviceId.slice(0, 8)}`,
    kind,
    groupId: device.groupId,
  }
}

/**
 * Keeps the current device when it is still plugged in, otherwise selects the
 * first available one. Never invents an id when there is nothing to select.
 */
export function pickDeviceId(currentId: string, devices: AudioDeviceInfo[]): string {
  if (currentId && devices.some(device => device.deviceId === currentId)) return currentId
  return devices[0]?.deviceId ?? currentId
}

/** Device listing for the settings page. Pure listing, no connection involved. */
export function useVoiceDevices() {
  const availableInputDevices = ref<AudioDeviceInfo[]>([])
  const availableOutputDevices = ref<AudioDeviceInfo[]>([])

  function setInputDevices(devices: AudioDeviceInfo[]) {
    availableInputDevices.value = devices
  }

  function setOutputDevices(devices: AudioDeviceInfo[]) {
    availableOutputDevices.value = devices
  }

  async function requestDevicePermissions() {
    try {
      await navigator.mediaDevices.getUserMedia({ audio: true, video: false })
    } catch {
      // Permission denied, but we still want to list devices
    }
  }

  /**
   * Refreshes the input list and returns the id to select. The caller stores
   * it (persisted), this module only lists.
   */
  async function refreshInputDevices(currentId: string): Promise<string> {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices()
      const audioInputs = devices
        .filter(device => device.kind === 'audioinput')
        .map(device => toAudioDevice(device, 'audioinput', 'Microphone'))
      availableInputDevices.value = audioInputs
      return pickDeviceId(currentId, audioInputs)
    } catch (err) {
      console.error('Failed to enumerate input devices:', err)
      return currentId
    }
  }

  /** Same as refreshInputDevices, for outputs. */
  async function refreshOutputDevices(currentId: string): Promise<string> {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices()
      const audioOutputs = devices
        .filter(device => device.kind === 'audiooutput')
        .map(device => toAudioDevice(device, 'audiooutput', 'Speaker'))
      availableOutputDevices.value = audioOutputs
      return pickDeviceId(currentId, audioOutputs)
    } catch (err) {
      console.error('Failed to enumerate output devices:', err)
      return currentId
    }
  }

  return {
    availableInputDevices,
    availableOutputDevices,
    setInputDevices,
    setOutputDevices,
    requestDevicePermissions,
    refreshInputDevices,
    refreshOutputDevices,
  }
}
