import { IceServerConfig } from './types.js';

export const DEFAULT_STUN_SERVERS: IceServerConfig[] = [
  { urls: 'stun:stun.l.google.com:19302' },
  { urls: 'stun:stun1.l.google.com:19302' },
  { urls: 'stun:stun2.l.google.com:19302' },
  { urls: 'stun:stun3.l.google.com:19302' },
  { urls: 'stun:stun4.l.google.com:19302' },
];

export const DEFAULT_ICE_SERVERS: IceServerConfig[] = [
  ...DEFAULT_STUN_SERVERS,
];

export type IceCandidateType = 'host' | 'srflx' | 'prflx' | 'relay';

export const ALLOWED_CANDIDATE_TYPES: IceCandidateType[] = [
  'host',
  'srflx',
  'relay',
];

export interface IceManagerConfig {
  iceServers?: IceServerConfig[];
  allowedCandidateTypes?: IceCandidateType[];
}

export class IceManager {
  private iceServers: IceServerConfig[];
  private allowedCandidateTypes: IceCandidateType[];

  constructor(config: IceManagerConfig = {}) {
    this.iceServers = config.iceServers?.length
      ? config.iceServers
      : DEFAULT_ICE_SERVERS;
    this.allowedCandidateTypes = config.allowedCandidateTypes ?? ALLOWED_CANDIDATE_TYPES;
  }

  getIceServers(): IceServerConfig[] {
    return this.iceServers;
  }

  getRTCIceServers(): RTCIceServer[] {
    return this.iceServers.map((server) => ({
      urls: server.urls,
      username: server.username,
      credential: server.credential,
    }));
  }

  filterCandidate(candidate: RTCIceCandidateInit): boolean {
    if (!candidate.candidate) return false;

    const typeMatch = candidate.candidate.match(/typ\s+(\w+)/);
    if (!typeMatch) return false;

    const candidateType = typeMatch[1] as IceCandidateType;
    return this.allowedCandidateTypes.includes(candidateType);
  }

  filterCandidates(candidates: RTCIceCandidateInit[]): RTCIceCandidateInit[] {
    return candidates.filter((c) => this.filterCandidate(c));
  }

  addIceServer(server: IceServerConfig): void {
    this.iceServers.push(server);
  }

  setIceServers(servers: IceServerConfig[]): void {
    this.iceServers = servers.length ? servers : DEFAULT_ICE_SERVERS;
  }

  setAllowedCandidateTypes(types: IceCandidateType[]): void {
    this.allowedCandidateTypes = types.length ? types : ALLOWED_CANDIDATE_TYPES;
  }

  static createFromSignalingConfig(servers: IceServerConfig[]): IceManager {
    const merged = [...DEFAULT_STUN_SERVERS, ...servers];
    return new IceManager({ iceServers: merged });
  }
}

export const iceManager = new IceManager();