import { ref } from 'vue'
import type { VoiceSettings } from '@/types'

const STORAGE_KEY = 'voiceSettings'

const DEFAULT_SETTINGS: VoiceSettings = {
  inputDeviceId: '',
  outputDeviceId: '',
  inputVolume: 1.0,
  outputVolume: 1.0,
  noiseSuppression: true,
  noiseSuppressionLevel: 0.5,
  echoCancellation: true,
  autoGainControl: true,
  spatialAudio: true,
  pushToTalk: false,
  pushToTalkKey: 'KeyV',
  voiceActivationThreshold: -40,
}

/** The persisted settings from the settings page. Every change is stored at once. */
export function useVoiceSettings() {
  const settings = ref<VoiceSettings>({ ...DEFAULT_SETTINGS })

  function updateSettings(newSettings: Partial<VoiceSettings>) {
    settings.value = { ...settings.value, ...newSettings }
    persistSettings()
  }

  function persistSettings() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings.value))
  }

  function restoreSettings() {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored) {
      try {
        settings.value = { ...settings.value, ...JSON.parse(stored) }
      } catch {
        // Ignore invalid settings
      }
    }
  }

  return { settings, updateSettings, persistSettings, restoreSettings }
}
