/**
 * The wire protocol for SVC groups, shared by the mod GUI, the direct
 * WebSocket transport and the PeerJS data channel transport.
 *
 * Everything here mirrors what the plugin really sends and expects. Both
 * transports import these names, so a rename can only ever break one place.
 */

/** The three group types Simple Voice Chat supports. */
export const GROUP_TYPES = ['normal', 'open', 'isolated'] as const

export type GroupType = (typeof GROUP_TYPES)[number]

export function isGroupType(value: unknown): value is GroupType {
  return typeof value === 'string' && (GROUP_TYPES as readonly string[]).includes(value)
}

/**
 * The plugin reports the type as a plain lower case name ("normal", "open",
 * "isolated"). Older builds and the mod's own toString can leak a Java class
 * name such as "Group$Type$1@1a2b3c" into this field, so anything unknown is
 * shown as a normal group instead of raw Java noise.
 */
export function normalizeGroupType(value: unknown): GroupType {
  const raw = typeof value === 'string' ? value.trim().toLowerCase() : ''
  if (raw === 'open') return 'open'
  if (raw === 'isolated') return 'isolated'
  // A class name is never a real type, so it must not become the label.
  if (raw.includes('$') || raw.includes('@') || raw.includes('.')) return 'normal'
  return 'normal'
}

/** The server rejects a name outside this range, so the UI checks it too. */
export const GROUP_NAME_MIN_LENGTH = 1
/**
 * 16, not 24: Simple Voice Chat stores what Group.Builder.setName hands it, and
 * that runs convertGroupName, which does substring(0, 16). A longer name is
 * accepted by the SVC regex and then silently shortened, so the browser refuses
 * it up front and says why.
 */
export const GROUP_NAME_MAX_LENGTH = 16

/**
 * Returns a language-file key (or null when valid), never display text: the
 * caller renders it with `t(key, { max })`, so the message follows the UI
 * language with English as fallback.
 */
export function validateGroupName(name: string): string | null {
  const trimmed = name.trim()
  if (trimmed.length < GROUP_NAME_MIN_LENGTH) return 'group.error.nameEmpty'
  if (trimmed.length > GROUP_NAME_MAX_LENGTH) {
    return 'group.error.nameTooLong'
  }
  return null
}

/** One SVC group, exactly as the plugin describes it. */
export interface GroupInfo {
  /** True when the group is protected. The browser then has to ask for it. */
  hasPassword?: boolean;
  id: string
  name: string
  persistent: boolean
  type: GroupType
  /** Mod players plus browser peers. */
  participants: number
  /** Members who are Simple Voice Chat mod players. */
  modPlayers: number
  /** Members who are browsers. */
  webParticipants: number
}

export interface GroupJoinedPayload {
  groupId: string
  groupName: string
  roomId: string
}

export interface GroupLeftPayload {
  groupId: string
}

export interface GroupListPayload {
  groups: GroupInfo[]
}

/**
 * The plugin's error payload. The code is a number on the wire (1002, 1003,
 * 1004, ...), so it is parsed defensively and never trusted as a string.
 */
export interface GroupErrorPayload {
  code: number
  message: string
}

/**
 * Request and answer message names. The plugin answers every request, but the
 * answer is a broadcast, so the names are what a request waits for.
 */
export const GROUP_REQUEST = {
  list: 'group-list',
  create: 'group-create',
  join: 'group-join',
  leave: 'group-leave',
  delete: 'group-delete',
} as const

export const GROUP_RESPONSE = {
  list: 'group-list',
  created: 'group-created',
  joined: 'group-joined',
  left: 'group-left',
  error: 'error',
} as const

export type GroupRequestType = (typeof GROUP_REQUEST)[keyof typeof GROUP_REQUEST]

/**
 * Every group request carries this id, and only the answer with the same id
 * settles the request. Without it a list refresh, which the plugin sends right
 * after a create or a delete, is picked up by the waiting request and settles
 * it with the wrong payload.
 */
export type GroupRequestId = string

/** A request as it goes out over the wire. */
export interface GroupRequestMessage<TPayload = unknown> {
  type: GroupRequestType
  payload: TPayload
  requestId: GroupRequestId
}

/** An answer as it arrives from the plugin. */
export interface GroupResponseMessage<TPayload = unknown> {
  type: string
  payload: TPayload
  requestId?: GroupRequestId
}

/** Reads the request id out of an arbitrary inbound message. */
export function readRequestId(message: unknown): GroupRequestId | undefined {
  if (!message || typeof message !== 'object') return undefined
  const value = (message as Record<string, unknown>)['requestId']
  return typeof value === 'string' && value.length > 0 ? value : undefined
}

/** Reads the message name out of an arbitrary inbound message. */
export function readType(message: unknown): string | undefined {
  if (!message || typeof message !== 'object') return undefined
  const value = (message as Record<string, unknown>)['type']
  return typeof value === 'string' ? value : undefined
}

export function readPayload(message: unknown): unknown {
  if (!message || typeof message !== 'object') return undefined
  return (message as Record<string, unknown>)['payload']
}

/**
 * Turns one entry of the plugin's group list into a `GroupInfo`. A malformed
 * entry is dropped instead of reaching the UI as "undefined", and a missing
 * participant count falls back to the mod players so the list still adds up.
 */
export function toGroupInfo(value: unknown): GroupInfo | null {
  if (!value || typeof value !== 'object') return null
  const raw = value as Record<string, unknown>
  const id = raw['id']
  const name = raw['name']
  if (typeof id !== 'string' || id.length === 0) return null
  if (typeof name !== 'string') return null

  const toCount = (input: unknown) =>
    typeof input === 'number' && Number.isFinite(input) && input >= 0 ? Math.floor(input) : 0

  const modPlayers = toCount(raw['modPlayers'])
  const webParticipants = toCount(raw['webParticipants'])
  const participants = raw['participants'] === undefined ? modPlayers + webParticipants : toCount(raw['participants'])

  return {
    id,
    name,
    hasPassword: raw['hasPassword'] === true,
    persistent: raw['persistent'] === true,
    type: normalizeGroupType(raw['type']),
    participants,
    modPlayers,
    webParticipants,
  }
}

/** Parses a group list payload, dropping anything unusable. */
export function toGroupList(payload: unknown): GroupInfo[] {
  const list = readPayload(payload) ?? payload
  if (!list || typeof list !== 'object') return []
  const groups = (list as Record<string, unknown>)['groups']
  if (!Array.isArray(groups)) return []
  return groups
    .map(toGroupInfo)
    .filter((group): group is GroupInfo => group !== null)
}

/**
 * Parses an error answer into a message the user can read. The plugin sends a
 * number, but a string code is accepted too, and a message that is missing
 * falls back to a generic reason instead of showing nothing at all.
 */
export function toGroupError(payload: unknown, fallback: string): GroupErrorPayload {
  const raw = (payload && typeof payload === 'object' ? payload : {}) as Record<string, unknown>
  const message = raw['message']
  const code = raw['code']
  return {
    code: typeof code === 'number' ? code : typeof code === 'string' ? Number(code) || 0 : 0,
    message: typeof message === 'string' && message.trim().length > 0 ? message : fallback,
  }
}

/** Creates the correlation id for one request. */
export function newRequestId(): GroupRequestId {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID()
  }
  return `g-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
}
