/**
 * Minimal key-based i18n, the way the mod does it: the code holds keys,
 * `src/lang/<locale>.json` holds the display strings, English is the
 * complete fallback. A missing key in the active language falls back to
 * English, then to the key itself, so an incomplete translation never
 * renders blank. Adding a language = one JSON file + one line below.
 */
import { ref } from 'vue'
import en from './lang/en.json'
import de from './lang/de.json'

export type Locale = 'de' | 'en'

const catalogs: Record<Locale, Record<string, string>> = { de, en }
const STORAGE_KEY = 'svc-locale'

function detectLocale(): Locale {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === 'de' || stored === 'en') return stored
  } catch {
    // Private mode or no DOM (tests): fall through to the browser language.
  }
  if (typeof navigator !== 'undefined' && navigator.language.toLowerCase().startsWith('de')) {
    return 'de'
  }
  return 'en'
}

/**
 * Reactive on purpose: reading it inside `t()` in a template subscribes the
 * component, so `setLocale` re-renders every visible string at once. Outside
 * components (stores, transport classes) it is just the current value.
 */
export const locale = ref<Locale>(detectLocale())

function syncDocumentLocale(value: Locale) {
  if (typeof document !== 'undefined') {
    document.documentElement.lang = value
  }
}

syncDocumentLocale(locale.value)

export function setLocale(value: Locale): void {
  locale.value = value
  try {
    localStorage.setItem(STORAGE_KEY, value)
  } catch {
    // Private mode: the choice lasts until reload, same as before.
  }
  syncDocumentLocale(value)
}

export function t(key: string, params?: Record<string, string | number>): string {
  // Track the reactive locale so templates update on language switch.
  const active = locale.value
  const table = catalogs[active] ?? {}
  let text = table[key] ?? catalogs.en[key] ?? key
  if (params) {
    // ES2020 target: no String.replaceAll, split/join does the same.
    for (const [name, value] of Object.entries(params)) {
      text = text.split(`{${name}}`).join(String(value))
    }
  }
  return text
}
