import type { LoginCredentials, RegisterData, AuthResponse, User } from '../types'
import { t } from '@/i18n'

const API_BASE = import.meta.env.VITE_API_BASE || '/api'

interface WorkerResponse<T> {
  success: boolean
  data?: T
  error?: { code: string; message: string }
}

async function fetchApi<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
  const url = `${API_BASE}${endpoint}`

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  }

  if (options.headers) {
    if (Array.isArray(options.headers)) {
      options.headers.forEach(([key, value]) => { headers[key] = value })
    } else if (options.headers instanceof Headers) {
      options.headers.forEach((value, key) => { headers[key] = value })
    } else {
      Object.assign(headers, options.headers)
    }
  }

  const token = localStorage.getItem('auth')
  if (token) {
    try {
      const authData = JSON.parse(token)
      if (authData.token) {
        headers['Authorization'] = `Bearer ${authData.token}`
      }
    } catch {
      // Invalid token, ignore
    }
  }

  const response = await fetch(url, {
    ...options,
    headers,
  })

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}))
    throw new Error(errorData.message || `HTTP ${response.status}: ${response.statusText}`)
  }

  if (response.status === 204) {
    return undefined as T
  }

  return response.json()
}

export async function login(credentials: LoginCredentials): Promise<AuthResponse> {
  return fetchApi<AuthResponse>('/auth/login', {
    method: 'POST',
    body: JSON.stringify(credentials),
  })
}

export async function register(data: RegisterData): Promise<AuthResponse> {
  return fetchApi<AuthResponse>('/auth/register', {
    method: 'POST',
    body: JSON.stringify(data),
  })
}

export async function logout(): Promise<void> {
  return fetchApi<void>('/auth/logout', {
    method: 'POST',
  })
}

export async function refreshToken(): Promise<AuthResponse> {
  return fetchApi<AuthResponse>('/auth/refresh', {
    method: 'POST',
  })
}

export async function getCurrentUser(): Promise<User> {
  return fetchApi<User>('/auth/me')
}

export interface VoiceCodeAuth {
  token: string
  expiresAt: number
  playerUuid: string
  playerName: string
}

export async function verifyVoiceCode(code: string): Promise<VoiceCodeAuth> {
  const response = await fetch(`${API_BASE}/auth/verify`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ code: code.toUpperCase() }),
  })
  const payload = await response.json() as WorkerResponse<VoiceCodeAuth>
  if (!response.ok || !payload.success || !payload.data) {
    throw new Error(payload.error?.message ?? t('auth.error.check', { status: response.status }))
  }
  return payload.data
}

export async function updateProfile(data: Partial<User>): Promise<User> {
  return fetchApi<User>('/auth/profile', {
    method: 'PATCH',
    body: JSON.stringify(data),
  })
}

export async function changePassword(
  currentPassword: string,
  newPassword: string
): Promise<void> {
  return fetchApi<void>('/auth/password', {
    method: 'POST',
    body: JSON.stringify({ currentPassword, newPassword }),
  })
}
