export const OPUS_CODEC_PARAMS = {
  maxaveragebitrate: 64000,
  stereo: 0,
  useinbandfec: 1,
  usedtx: 1,
  maxplaybackrate: 48000,
  ptime: 20,
  minptime: 10,
} as const;

export const AUDIO_CONSTRAINTS: MediaTrackConstraints = {
  sampleRate: 48000,
  channelCount: 1,
  echoCancellation: true,
  noiseSuppression: true,
  autoGainControl: true,
} as const;

/** The three browser-native voice processing toggles from the settings page. */
export interface AudioProcessingSettings {
  echoCancellation: boolean;
  noiseSuppression: boolean;
  autoGainControl: boolean;
  inputDeviceId?: string;
}

/**
 * Builds the getUserMedia audio constraints from the user's toggles. The base
 * (48 kHz mono) never changes, only the processing flags do. The settings page
 * always wrote these values, but both call sites used the hardcoded constant
 * above, so the toggles did nothing until now. Applies on next connect.
 */
export function buildAudioConstraints(processing: AudioProcessingSettings): MediaTrackConstraints {
  return {
    ...AUDIO_CONSTRAINTS,
    echoCancellation: processing.echoCancellation,
    noiseSuppression: processing.noiseSuppression,
    autoGainControl: processing.autoGainControl,
    ...(processing.inputDeviceId ? { deviceId: { exact: processing.inputDeviceId } } : {}),
  };
}

export function applyOpusParams(sdp: string): string {
  const lines = sdp.split('\r\n');
  const result: string[] = [];

  for (const line of lines) {
    if (line.startsWith('a=fmtp:') && line.includes('opus/48000')) {
      const params = Object.entries(OPUS_CODEC_PARAMS)
        .map(([key, value]) => `${key}=${value}`)
        .join(';');
      result.push(`a=fmtp:111 ${params}`);
    } else {
      result.push(line);
    }
  }

  return result.join('\r\n');
}

interface RTCRtpCodecCapability {
  mimeType: string;
  clockRate: number;
  channels: number;
  sdpFmtpLine?: string;
}

export function getPreferredCodecs(): RTCRtpCodecCapability[] {
  return [
    {
      mimeType: 'audio/opus',
      clockRate: 48000,
      channels: 1,
      sdpFmtpLine: Object.entries(OPUS_CODEC_PARAMS)
        .map(([key, value]) => `${key}=${value}`)
        .join(';'),
    },
    {
      mimeType: 'audio/PCMU',
      clockRate: 8000,
      channels: 1,
    },
    {
      mimeType: 'audio/PCMA',
      clockRate: 8000,
      channels: 1,
    },
  ] as const;
}
