import { ref } from 'vue'

const STORAGE_KEY = 'svc-connection-diagnostics'
const MAX_ENTRIES = 500

/** Reads the persisted diagnostics log, tolerating missing or corrupt storage. */
export function loadConnectionDiagnostics(): string[] {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    const entries: unknown = stored ? JSON.parse(stored) : []
    return Array.isArray(entries)
      ? entries.filter((entry): entry is string => typeof entry === 'string').slice(-MAX_ENTRIES)
      : []
  } catch { return [] }
}

/** The persisted WebRTC/Signaling event log, newest last, capped in memory and storage. */
export function useConnectionDiagnostics() {
  const connectionDiagnostics = ref<string[]>(loadConnectionDiagnostics())

  function addConnectionDiagnostic(message: string) {
    const entry = `${new Date().toISOString()} ${message}`
    connectionDiagnostics.value = [...connectionDiagnostics.value.slice(-(MAX_ENTRIES - 1)), entry]
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(connectionDiagnostics.value))
    } catch { /* Keep the live log available when storage is unavailable or full. */ }
  }

  function clearConnectionDiagnostics() {
    connectionDiagnostics.value = []
    try { localStorage.removeItem(STORAGE_KEY) } catch { /* Storage is optional. */ }
  }

  return { connectionDiagnostics, addConnectionDiagnostic, clearConnectionDiagnostics }
}
