import {
  applyOpusParams,
  OPUS_CODEC_PARAMS,
  AUDIO_CONSTRAINTS,
  getPreferredCodecs,
} from './opus.js';
import { IceManager, DEFAULT_ICE_SERVERS } from './IceManager.js';
import type {
  IceServerConfig,
  PeerConnectionState,
  ConnectionState,
  IceConnectionState,
} from './types.js';

export interface WebRtcClientConfig {
  iceServers?: IceServerConfig[];
  /** Overrides the default microphone constraints (e.g. from the settings). */
  audioConstraints?: MediaTrackConstraints;
  onTrack?: (track: MediaStreamTrack, stream: MediaStream) => void;
  onIceCandidate?: (candidate: RTCIceCandidateInit) => void;
  onConnectionStateChange?: (state: ConnectionState) => void;
  onIceConnectionStateChange?: (state: IceConnectionState) => void;
  onNegotiationNeeded?: () => void;
}

export class WebRtcClient {
  private pc: RTCPeerConnection | null = null;
  private localStream: MediaStream | null = null;
  private config: Required<WebRtcClientConfig>;
  private iceManager: IceManager;
  private audioContext: AudioContext | null = null;
  private pannerNode: PannerNode | null = null;
  private gainNode: GainNode | null = null;

  constructor(config: WebRtcClientConfig = {}) {
    this.config = {
      iceServers: config.iceServers ?? DEFAULT_ICE_SERVERS,
      audioConstraints: config.audioConstraints ?? AUDIO_CONSTRAINTS,
      onTrack: config.onTrack ?? (() => {}),
      onIceCandidate: config.onIceCandidate ?? (() => {}),
      onConnectionStateChange: config.onConnectionStateChange ?? (() => {}),
      onIceConnectionStateChange: config.onIceConnectionStateChange ?? (() => {}),
      onNegotiationNeeded: config.onNegotiationNeeded ?? (() => {}),
    };
    this.iceManager = new IceManager({ iceServers: this.config.iceServers });
  }

  private createPeerConnection(): RTCPeerConnection {
    const pc = new RTCPeerConnection({
      iceServers: this.iceManager.getRTCIceServers(),
      iceTransportPolicy: 'all',
      bundlePolicy: 'max-bundle',
      rtcpMuxPolicy: 'require',
    });

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        const candidate = event.candidate.toJSON();
        if (this.iceManager.filterCandidate(candidate)) {
          this.config.onIceCandidate(candidate);
        }
      }
    };

    pc.ontrack = (event) => {
      const remoteStream = event.streams[0];
      const track = event.track ?? (remoteStream ? remoteStream.getAudioTracks()[0] : undefined);
      if (track && remoteStream) {
        this.config.onTrack(track, remoteStream);
      }
    };

    pc.onconnectionstatechange = () => {
      this.config.onConnectionStateChange(pc.connectionState as ConnectionState);
    };

    pc.oniceconnectionstatechange = () => {
      this.config.onIceConnectionStateChange(pc.iceConnectionState as IceConnectionState);
    };

    pc.onnegotiationneeded = () => {
      this.config.onNegotiationNeeded();
    };

    return pc;
  }

  async initialize(): Promise<void> {
    if (this.pc) {
      throw new Error('WebRtcClient already initialized');
    }

    this.pc = this.createPeerConnection();

    try {
      this.localStream = await navigator.mediaDevices.getUserMedia({
        audio: this.config.audioConstraints,
        video: false,
      });

      this.setupAudioProcessing();

      for (const track of this.localStream.getTracks()) {
        this.pc.addTrack(track, this.localStream);
      }
    } catch (error) {
      this.close();
      throw error;
    }
  }

  private setupAudioProcessing(): void {
    if (!this.localStream) return;

    this.audioContext = new AudioContext({ sampleRate: 48000, latencyHint: 'interactive' });
    const source = this.audioContext.createMediaStreamSource(this.localStream);

    this.pannerNode = this.audioContext.createPanner();
    this.pannerNode.panningModel = 'HRTF';
    this.pannerNode.distanceModel = 'inverse';
    this.pannerNode.refDistance = 1;
    this.pannerNode.maxDistance = 100;
    this.pannerNode.rolloffFactor = 1;
    this.pannerNode.coneInnerAngle = 360;
    this.pannerNode.coneOuterAngle = 360;
    this.pannerNode.coneOuterGain = 0;

    this.gainNode = this.audioContext.createGain();
    this.gainNode.gain.value = 1.0;

    // Route the processed track back into WebRTC only. Playing the microphone
    // locally would create an avoidable echo; remote audio is rendered by the
    // server connection when its track arrives.
    source.connect(this.pannerNode).connect(this.gainNode);

    const [audioTrack] = this.localStream.getAudioTracks();
    if (audioTrack) {
      const processedStream = this.audioContext.createMediaStreamDestination();
      this.gainNode.connect(processedStream);
      this.localStream.removeTrack(audioTrack);
      const processedTrack = processedStream.stream.getAudioTracks()[0];
      if (processedTrack) {
        this.localStream.addTrack(processedTrack);

        if (this.pc) {
          const sender = this.pc.getSenders().find((s) => s.track === audioTrack);
          if (sender) {
            sender.replaceTrack(processedStream.stream.getAudioTracks()[0] ?? null);
          }
        }
      }
    }
  }

  setPosition(x: number, y: number, z: number): void {
    if (this.pannerNode) {
      this.pannerNode.positionX.setValueAtTime(x, this.audioContext!.currentTime);
      this.pannerNode.positionY.setValueAtTime(y, this.audioContext!.currentTime);
      this.pannerNode.positionZ.setValueAtTime(z, this.audioContext!.currentTime);
    }
  }

  setVolume(volume: number): void {
    if (this.gainNode) {
      this.gainNode.gain.setValueAtTime(Math.max(0, Math.min(1, volume)), this.audioContext!.currentTime);
    }
  }

  setMuted(muted: boolean): void {
    if (this.localStream) {
      for (const track of this.localStream.getAudioTracks()) {
        track.enabled = !muted;
      }
    }
  }

  async createOffer(): Promise<RTCSessionDescriptionInit> {
    if (!this.pc) throw new Error('PeerConnection not initialized');

    const offer = await this.pc.createOffer({
      offerToReceiveAudio: true,
      offerToReceiveVideo: false,
    });

    const mungedSdp = applyOpusParams(offer.sdp!);
    const processedOffer: RTCSessionDescriptionInit = { ...offer, sdp: mungedSdp };

    await this.pc.setLocalDescription(processedOffer);
    return processedOffer;
  }

  async createAnswer(offer: RTCSessionDescriptionInit): Promise<RTCSessionDescriptionInit> {
    if (!this.pc) throw new Error('PeerConnection not initialized');

    await this.pc.setRemoteDescription(new RTCSessionDescription(offer));

    const answer = await this.pc.createAnswer();

    const mungedSdp = applyOpusParams(answer.sdp!);
    const processedAnswer: RTCSessionDescriptionInit = { ...answer, sdp: mungedSdp };

    await this.pc.setLocalDescription(processedAnswer);
    return processedAnswer;
  }

  async setLocalDescription(desc: RTCSessionDescriptionInit): Promise<void> {
    if (!this.pc) throw new Error('PeerConnection not initialized');
    await this.pc.setLocalDescription(new RTCSessionDescription(desc));
  }

  async setRemoteDescription(desc: RTCSessionDescriptionInit): Promise<void> {
    if (!this.pc) throw new Error('PeerConnection not initialized');
    await this.pc.setRemoteDescription(new RTCSessionDescription(desc));
  }

  async addIceCandidate(candidate: RTCIceCandidateInit): Promise<void> {
    if (!this.pc) throw new Error('PeerConnection not initialized');
    if (this.iceManager.filterCandidate(candidate)) {
      await this.pc.addIceCandidate(new RTCIceCandidate(candidate));
    }
  }

  addLocalTrack(track: MediaStreamTrack): void {
    if (!this.pc) throw new Error('PeerConnection not initialized');
    if (!this.localStream) {
      this.localStream = new MediaStream();
    }
    this.localStream.addTrack(track);
    this.pc.addTrack(track, this.localStream);
  }

  getConnectionState(): ConnectionState {
    return this.pc?.connectionState ?? 'new';
  }

  getIceConnectionState(): IceConnectionState {
    return this.pc?.iceConnectionState ?? 'new';
  }

  getLocalStream(): MediaStream | null {
    return this.localStream;
  }

  getPeerConnection(): RTCPeerConnection | null {
    return this.pc;
  }

  getAudioContext(): AudioContext | null {
    return this.audioContext;
  }

  getPannerNode(): PannerNode | null {
    return this.pannerNode;
  }

  getGainNode(): GainNode | null {
    return this.gainNode;
  }

  getIceManager(): IceManager {
    return this.iceManager;
  }

  async restartIce(): Promise<void> {
    if (!this.pc) throw new Error('PeerConnection not initialized');
    await this.pc.restartIce();
  }

  close(): void {
    if (this.pc) {
      this.pc.onicecandidate = null;
      this.pc.ontrack = null;
      this.pc.onconnectionstatechange = null;
      this.pc.oniceconnectionstatechange = null;
      this.pc.onnegotiationneeded = null;

      for (const sender of this.pc.getSenders()) {
        sender.track?.stop();
      }

      this.pc.close();
      this.pc = null;
    }

    if (this.localStream) {
      for (const track of this.localStream.getTracks()) {
        track.stop();
      }
      this.localStream = null;
    }

    if (this.audioContext) {
      this.audioContext.close();
      this.audioContext = null;
    }

    this.pannerNode = null;
    this.gainNode = null;
  }
}

export async function createWebRtcClient(config?: WebRtcClientConfig): Promise<WebRtcClient> {
  const client = new WebRtcClient(config);
  await client.initialize();
  return client;
}
